const axios = require('axios');
const SUPABASE_URL = $env.SUPABASE_URL;
const SERVICE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, 'Content-Type': 'application/json' };

let blueVenta;
let oficialVenta;
try {
  const { data } = await axios.get('https://dolarapi.com/v1/dolares', { timeout: 15000 });
  const blue = data.find((d) => d.casa === 'blue');
  const oficial = data.find((d) => d.casa === 'oficial');
  if (!blue || !oficial) throw new Error('dolarapi no devolvio blue/oficial');
  blueVenta = blue.venta;
  oficialVenta = oficial.venta;
} catch (error) {
  throw new Error(`No pude obtener el tipo de cambio: ${error.message}`);
}

const hoyAR = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' });

try {
  await axios.post(`${SUPABASE_URL}/rest/v1/tipo_cambio`, {
    fecha: hoyAR,
    blue_venta: blueVenta,
    oficial_venta: oficialVenta
  }, {
    headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=minimal' }
  });
} catch (error) {
  throw new Error(`No pude guardar el tipo de cambio: ${error.message}`);
}

return [{ json: { blueVenta, oficialVenta, fecha: hoyAR } }];

